CREATE OR REPLACE FUNCTION buildpulse_search_editions(p_query TEXT DEFAULT NULL,p_type TEXT DEFAULT NULL,p_limit INTEGER DEFAULT 24,p_offset INTEGER DEFAULT 0) RETURNS TABLE(id UUID,edition_type TEXT,subject TEXT,slug TEXT,public_excerpt TEXT,preheader TEXT,published_at TIMESTAMPTZ,pdf_path TEXT,rank REAL) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT e.id,e.edition_type,e.subject,e.slug,e.public_excerpt,e.preheader,e.published_at,e.pdf_path,CASE WHEN coalesce(trim(p_query),'')='' THEN 0::real ELSE ts_rank_cd(to_tsvector('english',coalesce(e.subject,'')||' '||coalesce(e.public_excerpt,'')||' '||coalesce(e.preheader,'')),websearch_to_tsquery('english',p_query)) END::real FROM buildpulse_editions e WHERE e.status='sent' AND e.archive_visible=true AND (p_type IS NULL OR p_type='' OR e.edition_type=p_type) AND (coalesce(trim(p_query),'')='' OR to_tsvector('english',coalesce(e.subject,'')||' '||coalesce(e.public_excerpt,'')||' '||coalesce(e.preheader,'')) @@ websearch_to_tsquery('english',p_query)) ORDER BY 9 DESC,e.published_at DESC NULLS LAST LIMIT greatest(1,least(p_limit,100)) OFFSET greatest(p_offset,0) $$;
REVOKE ALL ON FUNCTION buildpulse_search_editions(TEXT,TEXT,INTEGER,INTEGER) FROM PUBLIC; GRANT EXECUTE ON FUNCTION buildpulse_search_editions(TEXT,TEXT,INTEGER,INTEGER) TO anon,authenticated,service_role;
